import {parseCSV,sampleData,backtest,createReplay,advanceReplay,metrics} from './engine.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(x),pct=x=>(x*100).toFixed(2)+'%';
const key='tradoor.research.v1';let state;
try{state=JSON.parse(localStorage.getItem(key));}catch{}
if(!state||state.version!==1) state={version:1,csv:sampleData(),source:'Synthetic sample · not market data',runs:[],paper:null};
let data;try{data=parseCSV(state.csv);}catch{state={version:1,csv:sampleData(),source:'Synthetic sample · not market data',runs:[],paper:null};data=parseCSV(state.csv);}
let selectedMode='momentum';
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Storage is full or unavailable. Export your workspace before leaving.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function title(kicker,name,description,action=''){return `<div class="page-title"><div><div class="eyebrow">${kicker}</div><h1>${name}</h1><p>${description}</p></div>${action}</div>`;}
function notice(){return `<div class="notice"><strong>${esc(state.source)}</strong><span>Daily crypto research · 1× gross exposure · browser-local workspace</span><a href="#data">Manage data ↗</a></div>`;}
function chart(curve){if(!curve?.length)return '<div class="empty">Run a backtest to see an equity curve.</div>';const values=curve.map(p=>p.equity),min=Math.min(...values),max=Math.max(...values),range=Math.max(max-min,1),points=values.map((v,i)=>`${(i/Math.max(1,values.length-1)*800).toFixed(2)},${(215-(v-min)/range*190).toFixed(2)}`).join(' ');return `<svg class="chart" viewBox="0 0 800 240" preserveAspectRatio="none" role="img" aria-label="Equity curve from ${esc(curve[0].date)} to ${esc(curve.at(-1).date)}, range ${money(min)} to ${money(max)}"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#71976a" stop-opacity=".20"/><stop offset="100%" stop-color="#71976a" stop-opacity="0"/></linearGradient></defs>${[25,72,120,168,215].map(y=>`<line class="chart-grid" x1="0" y1="${y}" x2="800" y2="${y}"/>`).join('')}<polygon class="chart-area" points="0,240 ${points} 800,240"/><polyline class="chart-line" points="${points}"/></svg><div class="chart-labels"><span>${esc(curve[0].date)}</span><span>${money(min)} – ${money(max)}</span><span>${esc(curve.at(-1).date)}</span></div>`;}
function stats(run){const m=run?.metrics|| (run?metrics(run.curve,run.config.capital):null);return `<div class="stats">${[['Portfolio equity',run?money(run.equity):'—',run?'Marked at final close':'No research run yet'],['Total return',m?pct(m.totalReturn):'—','Net of configured fees & slippage'],['Sharpe ratio',m?.sharpe==null?'—':m.sharpe.toFixed(2),'365 daily periods · zero risk-free rate'],['Max drawdown',m?pct(m.maxDrawdown):'—',m?m.bars+' evaluation days':'Peak-to-trough equity decline']].map(([label,value,note])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
function runTable(){return state.runs.length?`<div class="table-scroll"><table><thead><tr><th>STRATEGY</th><th>RETURN</th><th>SHARPE</th><th>MAX DRAWDOWN</th><th>STATUS</th><th></th></tr></thead><tbody>${state.runs.map((r,i)=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.source)} · ${r.config.lookback}D lookback</small></td><td class="${r.metrics.totalReturn>=0?'positive':'negative'}">${pct(r.metrics.totalReturn)}</td><td>${r.metrics.sharpe?.toFixed(2)??'—'}</td><td>${pct(r.metrics.maxDrawdown)}</td><td><span class="badge">${esc(r.status)}</span></td><td><button class="button-small" data-export="${i}">Export</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your research starts here. Configure and run your first backtest.</div>';}
function overview(){const run=state.runs[0];return title('YOUR RESEARCH, IN FOCUS','Build conviction. Then trade.','One workspace to research signals, test strategies, and track simulations.','<a href="#backtests"><button class="primary">＋ New backtest</button></a>')+notice()+stats(run)+`<div class="grid"><section class="card"><div class="card-head"><div><h2>Portfolio performance</h2><small>${run?esc(run.name):'No backtest selected'}</small></div><span class="badge neutral">${run?'HISTORICAL':'AWAITING RESEARCH'}</span></div><div class="card-body"><div class="legend"><span>Strategy equity · USD</span></div>${chart(run?.curve)}</div></section><section class="card"><div class="card-head"><h2>Your next steps</h2><span class="badge neutral">RESEARCH → EXECUTION</span></div><div class="card-body steps"><a class="step" href="#data"><div><h3>Choose your dataset</h3><p>Import daily close prices or explore the synthetic sample.</p></div></a><a class="step" href="#backtests"><div><h3>Test your hypothesis</h3><p>Rank assets, account for costs, inspect every fill.</p></div></a><a class="step" href="#paper"><div><h3>Replay a paper portfolio</h3><p>Advance historical dates with simulated capital.</p></div></a><a class="step" href="#live"><div><h3>Prepare for live execution</h3><p>Exchange integration and server deployment required.</p></div></a></div></section></div><section class="card"><div class="card-head"><h2>Recent strategies</h2><a class="positive" href="#backtests">View research ↗</a></div>${runTable()}</section>`;}
function research(){return title('FACTOR RESEARCH','Start with a signal.','Two transparent baseline factors. No AI mining or proprietary Quandora factors are connected.')+notice()+`<div class="factor-grid">${[['momentum','01 / TREND FOLLOWING','Cross-sectional momentum','Rank assets by trailing return. Allocate long exposure to the strongest assets and short exposure to the weakest.','score(t) = close(t) / close(t − lookback) − 1'],['reversal','02 / MEAN REVERSION','Cross-sectional reversal','Reverse the ranking: buy recent relative laggards and sell recent leaders. Test whether short-term moves revert.','score(t) = − trailing_return(t)']].map(([mode,kicker,name,desc,formula])=>`<section class="card factor-card"><div class="eyebrow">${kicker}</div><h2>${name}</h2><p>${desc}</p><div class="code mono">${formula}</div><p>Signal: daily close · allocation: 50% long / 50% short · execution assumption: same close, held into next day</p><div class="actions"><button data-factor="${mode}" class="primary">Configure backtest ↗</button></div></section>`).join('')}</div><div class="callout">These are independently implemented baseline signals, not mined alphas. Results are descriptive historical simulations. The engine assumes close-price fills, excludes funding, borrow, liquidation and margin mechanics, and does not include walk-forward or multiple-testing validation yet.</div>`;}
function form(){return `<form id="backtest-form"><div class="form-grid"><label>Strategy name<input name="name" value="${selectedMode==='momentum'?'Momentum':'Reversal'} baseline" maxlength="80" required></label><label>Signal<select name="mode"><option value="momentum" ${selectedMode==='momentum'?'selected':''}>Cross-sectional momentum</option><option value="reversal" ${selectedMode==='reversal'?'selected':''}>Cross-sectional reversal</option></select></label><label>Starting capital (USD)<input name="capital" type="number" value="100000" min="100" max="1000000000" required></label><label>Lookback (daily bars)<input name="lookback" type="number" value="20" min="1" max="${data.dates.length-2}" required></label><label>Assets per side<input name="selection" type="number" value="1" min="1" max="${Math.floor(data.symbols.length/2)}" required></label><label>Transaction fee (bps)<input name="feeBps" type="number" step=".1" value="5" min="0" max="500" required></label><label>Slippage (bps)<input name="slippageBps" type="number" step=".1" value="2" min="0" max="500" required></label></div><div class="actions"><button type="submit" class="primary">Run backtest →</button><span class="muted">${data.symbols.length} assets · ${data.dates.length} daily bars · daily rebalance</span></div><div id="form-error" class="error" role="alert"></div></form>`;}
function backtests(){return title('STRATEGY LAB','Put your hypothesis to the test.','Configure a long–short daily portfolio and inspect the results after trading costs.')+notice()+`<section class="card wide"><div class="card-head"><h2>New backtest</h2><span class="badge neutral">INDEPENDENT BROWSER ENGINE</span></div><div class="card-body">${form()}<details><summary>Methodology & limitations</summary><p>Signals use only prices through day t; trades assume fills at that close and earn returns from t to t+1. Exposure targets 50% long and 50% short before costs. Positions rebalance daily. Entry and rebalance turnover pay the configured fees and slippage. Final positions are marked to market, not liquidated. Crypto-style 365-day Sharpe, zero risk-free rate. No funding, borrow costs, market impact, margin, liquidation, walk-forward or out-of-sample evaluation. Same-close execution is optimistic; use this foundation for software evaluation.</p></details></div></section>${state.runs[0]?stats(state.runs[0])+`<section class="card wide"><div class="card-head"><h2>${esc(state.runs[0].name)}</h2><a href="#paper" class="positive">Create paper replay ↗</a></div><div class="card-body">${chart(state.runs[0].curve)}</div></section>`:''}<section class="card"><div class="card-head"><h2>Backtest history</h2><span class="badge neutral">${state.runs.length} SAVED</span></div>${runTable()}</section>`;}
function paper(){const p=state.paper;return title('SIMULATED CAPITAL','Paper trading, one day at a time.','Historical replay only. This preview does not consume a live price feed or run in the background.')+notice()+(!p?`<section class="card"><div class="card-head"><h2>Create historical paper replay</h2></div><div class="card-body"><p>Replay your latest backtest configuration using the same dataset and simulated starting capital. Each step processes one historical daily bar. No real orders are placed.</p><div class="actions"><button id="create-paper" class="primary" ${!state.runs.length?'disabled':''}>Create replay from latest backtest</button>${!state.runs.length?'<a href="#backtests">Run a backtest first ↗</a>':''}</div></div></section>`:stats(p)+`<section class="card wide"><div class="card-head"><div><h2>${esc(p.name)}</h2><small>Historical date: ${esc(data.dates[p.index])} · ${esc(p.source)}</small></div><span class="badge">${esc(p.status).toUpperCase()}</span></div><div class="card-body">${chart(p.curve)}<div class="balance-row"><span>${p.index-p.config.lookback} / ${data.dates.length-1-p.config.lookback} replay days</span><span>Gross target: 1× · Net target: 0%</span></div><div class="progress"><div style="width:${(p.index-p.config.lookback)/(data.dates.length-1-p.config.lookback)*100}%"></div></div><div class="actions"><button class="primary" id="step-paper" ${['complete','stopped'].includes(p.status)?'disabled':''}>Advance 1 day →</button><button id="week-paper" ${['complete','stopped'].includes(p.status)?'disabled':''}>Advance 7 days</button><button id="stop-paper" ${['complete','stopped'].includes(p.status)?'disabled':''}>Stop replay</button><button id="new-paper">New replay</button><button id="export-paper">Export fills</button></div></div></section><section class="card wide"><div class="card-head"><h2>Current simulated positions</h2><span class="badge neutral">MARKED AT REPLAY CLOSE</span></div><div class="table-scroll"><table><thead><tr><th>ASSET</th><th>SIDE</th><th>QUANTITY</th><th>MARK PRICE</th><th>NOTIONAL</th></tr></thead><tbody>${p.quantities.map((q,j)=>q?`<tr><td>${esc(data.symbols[j])}</td><td class="${q>0?'positive':'negative'}">${q>0?'Long':'Short'}</td><td>${Math.abs(q).toFixed(6)}</td><td>${money(data.prices[p.index][j])}</td><td>${money(Math.abs(q*data.prices[p.index][j]))}</td></tr>`:'').join('')||'<tr><td colspan="5">Advance a day to establish simulated positions.</td></tr>'}</tbody></table></div></section><section class="card"><div class="card-head"><h2>Recent simulated fills</h2><span class="badge neutral">${p.fills.length} TOTAL</span></div><div class="table-scroll"><table><thead><tr><th>DATE</th><th>ASSET</th><th>SIDE</th><th>QUANTITY</th><th>PRICE</th><th>FEE + SLIPPAGE</th></tr></thead><tbody>${p.fills.slice(-20).reverse().map(f=>`<tr><td>${f.date}</td><td>${esc(f.symbol)}</td><td>${f.side}</td><td>${f.quantity.toFixed(6)}</td><td>${money(f.price)}</td><td>${money(f.cost)}</td></tr>`).join('')||'<tr><td colspan="6">No simulated fills yet.</td></tr>'}</tbody></table></div></section>`);}
function live(){return title('LIVE EXECUTION','Connect with confidence.','Live trading is unavailable in this preview. No exchange credentials are collected.')+`<div class="grid"><section class="card"><div class="card-head"><h2>Exchange connections</h2><span class="badge neutral">NOT CONNECTED</span></div><div class="card-body"><h3>Binance & Hyperliquid</h3><p>The existing Alphaloop repository includes exchange adapters. They are not connected to this interface and have not been verified for production use in this session.</p><div class="actions"><button disabled>Connect exchange · backend required</button></div><div class="callout">A browser-only site cannot securely store exchange secrets or operate an always-on execution loop. Connect accounts through an authenticated server with encrypted secrets and testnet verification.</div></div></section><section class="card"><div class="card-head"><h2>Before going live</h2></div><div class="card-body"><ul class="checks"><li>Identity & tenant isolation<span>Required</span></li><li>Encrypted server-side key storage<span>Required</span></li><li>Testnet order lifecycle<span>Unverified</span></li><li>Reconciliation & duplicate prevention<span>Unverified</span></li><li>Position limits & emergency stop<span>Unverified</span></li><li>Always-on worker & alerts<span>Required</span></li></ul></div></section></div><div class="callout">Research preview access does not authorize live trades. Production activation will require your chosen venue, a testnet account, explicit capital and risk limits, and verification of the complete execution lifecycle.</div>`;}
function dataPage(){return title('DATA LIBRARY','Know what you’re testing.','Bring your own consecutive daily crypto closes. Imported data stays in this browser.')+`<section class="card wide"><div class="card-head"><h2>Active dataset</h2><span class="badge neutral">${state.source.startsWith('Synthetic')?'SYNTHETIC':'USER IMPORT'}</span></div><div class="card-body"><h3>${esc(state.source)}</h3><p>${data.symbols.length} assets · ${data.dates.length} dates · ${data.dates[0]} → ${data.dates.at(-1)}</p><p class="mono">${data.symbols.map(esc).join(' · ')}</p><div class="actions"><button id="download-data">Download active CSV</button><button id="sample-data">Use synthetic sample</button></div></div></section><section class="card"><div class="card-head"><h2>Import daily prices</h2></div><div class="card-body"><p>One row per date and symbol. Every asset must have a positive close on every date, including weekends. Maximum 100,000 rows and 2–100 assets. Changing the dataset clears local results and replay state.</p><div class="code mono">date,symbol,close\n2025-01-01,BTC,94500\n2025-01-01,ETH,3350\n2025-01-02,BTC,95200\n2025-01-02,ETH,3410</div><div class="actions"><label>Choose CSV<input id="csv-file" type="file" accept=".csv,text/csv"></label><button id="import-data" class="primary">Import dataset</button></div><div id="data-error" class="error" role="alert"></div></div></section>`;}
function settings(){return title('PLATFORM READINESS','A foundation you can inspect.','The preview implements local research workflows. Production infrastructure is still required.')+`<section class="card wide"><div class="card-head"><h2>Implementation status</h2></div><div class="card-body"><ul class="checks">${[['Daily CSV import & validation','Implemented',true],['Momentum & reversal backtests','Implemented',true],['Equity, return, drawdown, Sharpe & fills','Implemented',true],['Historical paper replay & local persistence','Implemented',true],['Authenticated multi-user storage','Not connected'],['Alphaloop Python engine integration','Not connected'],['AI factor mining & research memory','Not connected'],['Live-data paper trading worker','Not connected'],['Exchange execution & monitoring','Not connected'],['tradoor.app domain','DNS access needed']].map(([a,b,done])=>`<li>${a}<span class="${done?'done':''}">${b}</span></li>`).join('')}</ul><div class="actions"><button id="export-workspace">Export workspace backup</button><a href="https://github.com/juggernott/tradoor.app" target="_blank" rel="noopener"><button>Open existing repository ↗</button></a></div><p>Saved to this browser’s local storage. Exports may contain your imported price dataset and research results. No login, cross-device sync, account balances, exchange keys or order submission are implemented here.</p></div></section><section class="card"><div class="card-head"><h2>Source references</h2></div><div class="card-body"><p>Reference workflow inspected in the signed-in Quandora app: factor library, strategy workflows and paper-trading area. No account portfolio data or private factor source has been copied into this preview.</p><div class="actions"><a href="https://www.quandora.ai" target="_blank" rel="noopener">Quandora public website ↗</a><a href="https://github.com/varsity-tech-product/quandora-plugins" target="_blank" rel="noopener">Public integration documentation ↗</a></div></div></section>`;}
const pages={overview,research,backtests,paper,live,data:dataPage,settings};const names={overview:'Overview',research:'Factor research',backtests:'Backtesting',paper:'Paper trading',live:'Live trading',data:'Data library',settings:'Settings & readiness'};
function render(){const page=location.hash.slice(1)||'overview';$('#main').innerHTML=(pages[page]||overview)();$('#breadcrumb').textContent=names[page]||'Overview';document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));bind();}
function swapData(csv,source){const parsed=parseCSV(csv);if((state.runs.length||state.paper)&&!confirm('Replace the dataset and clear saved backtests and paper replay in this browser? Export a backup first if needed.'))return;data=parsed;state={version:1,csv,source,runs:[],paper:null};save();render();toast('Dataset loaded.');}
function bind(){
  document.querySelectorAll('[data-factor]').forEach(b=>b.onclick=()=>{selectedMode=b.dataset.factor;location.hash='backtests';});
  document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download('tradoor-backtest.json',JSON.stringify(state.runs[Number(b.dataset.export)],null,2),'application/json'));
  const formEl=$('#backtest-form');if(formEl)formEl.onsubmit=e=>{e.preventDefault();try{const f=new FormData(formEl),config={mode:f.get('mode'),capital:Number(f.get('capital')),lookback:Number(f.get('lookback')),selection:Number(f.get('selection')),feeBps:Number(f.get('feeBps')),slippageBps:Number(f.get('slippageBps'))};const run=backtest(data,config);run.name=String(f.get('name')).trim()||'Untitled strategy';run.source=state.source;run.created=new Date().toISOString();state.runs.unshift(run);state.runs=state.runs.slice(0,10);save();render();toast('Backtest complete. Results saved in this browser.');}catch(error){$('#form-error').textContent=error.message;}};
  if($('#create-paper'))$('#create-paper').onclick=()=>{const r=state.runs[0];state.paper={...createReplay(data,r.config),name:r.name,source:state.source};save();render();toast('Historical paper replay created.');};
  function step(count){try{for(let j=0;j<count;j++){if(['complete','stopped'].includes(state.paper.status))break;advanceReplay(data,state.paper);}save();render();}catch(e){toast(e.message);}}
  if($('#step-paper'))$('#step-paper').onclick=()=>step(1);if($('#week-paper'))$('#week-paper').onclick=()=>step(7);
  if($('#stop-paper'))$('#stop-paper').onclick=()=>{state.paper.status='stopped';save();render();toast('Replay stopped. Positions remain marked, without liquidation.');};
  if($('#new-paper'))$('#new-paper').onclick=()=>{if(confirm('Replace this historical replay with a new one? Export fills first if needed.')){state.paper=null;save();render();}};
  if($('#export-paper'))$('#export-paper').onclick=()=>download('tradoor-paper-fills.csv',['date,symbol,side,quantity,price,cost',...state.paper.fills.map(f=>[f.date,f.symbol,f.side,f.quantity,f.price,f.cost].join(','))].join('\n'),'text/csv');
  if($('#download-data'))$('#download-data').onclick=()=>download('tradoor-prices.csv',state.csv,'text/csv');
  if($('#sample-data'))$('#sample-data').onclick=()=>swapData(sampleData(),'Synthetic sample · not market data');
  if($('#import-data'))$('#import-data').onclick=async()=>{try{const file=$('#csv-file').files[0];if(!file)throw Error('Choose a CSV file first.');if(file.size>5e6)throw Error('CSV must be smaller than 5 MB.');swapData(await file.text(),'Imported CSV: '+file.name);}catch(e){$('#data-error').textContent=e.message;}};
  if($('#export-workspace'))$('#export-workspace').onclick=()=>download('tradoor-workspace.json',JSON.stringify(state,null,2),'application/json');
}
window.addEventListener('hashchange',render);render();save();
